func (b *BeaconState) Copy() state.BeaconState {
	b.lock.RLock()
	defer b.lock.RUnlock()

	dst := &BeaconState{
		// Primitive types, safe to copy.
		// ...

		// Large arrays via CoW multiValue:
		blockRootsMultiValue: b.blockRootsMultiValue,
		stateRootsMultiValue: b.stateRootsMultiValue,
		// ...

		// Slice header aliasing (tracked in sharedFieldReferences):
		previousEpochAttestations: b.previousEpochAttestations,
		currentEpochAttestations: b.currentEpochAttestations,
		eth1DataVotes: b.eth1DataVotes,
		slashings: b.slashings,
		proposerLookahead: b.proposerLookahead,
		pendingDeposits: b.pendingDeposits,
		pendingPartialWithdrawals: b.pendingPartialWithdrawals,
		pendingConsolidations: b.pendingConsolidations,
	}

	// Shared ref counts for CoW
	for field, ref := range b.sharedFieldReferences {
		ref.AddRef()
		dst.sharedFieldReferences[field] = ref
	}

	// stateFieldLeaves: pointer sharing with ref count
	for fldIdx, fieldTrie := range b.stateFieldLeaves {
		dst.stateFieldLeaves[fldIdx] = fieldTrie
		if fieldTrie.FieldReference() != nil {
			fieldTrie.Lock()
			fieldTrie.FieldReference().AddRef()
			fieldTrie.Unlock()
		}
	}

	// merkleLayers: deep copy
	if b.merkleLayers != nil {
		dst.merkleLayers = make([][][]byte, len(b.merkleLayers))
		for i, layer := range b.merkleLayers {
			dst.merkleLayers[i] = make([][]byte, len(layer))
			for j, content := range layer {
				dst.merkleLayers[i][j] = make([]byte, len(content))
				copy(dst.merkleLayers[i][j], content)
			}
		}
	}
}

